import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class CheckoutIntegrationTest {

    @Autowired
    private TestRestTemplate rest;

    private ResponseEntity<Map> post(String body) {
        return rest.postForEntity("/checkout/resumo", body, Map.class,
                new org.springframework.http.HttpEntity<>(body,
                        org.springframework.http.HttpHeaders.EMPTY));
    }

    private ResponseEntity<Map> resumo(String body) {
        var headers = new org.springframework.http.HttpHeaders();
        headers.set("Content-Type", "application/json");
        var entity = new org.springframework.http.HttpEntity<>(body, headers);
        return rest.postForEntity("/checkout/resumo", entity, Map.class);
    }

