1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.CartItem;
4	import com.loja.checkout.domain.CheckoutRequest;
5	import com.loja.checkout.domain.CheckoutResponse;
6	import com.loja.checkout.domain.ClubLevel;
7	import com.loja.checkout.domain.PaymentMethod;
8	import com.loja.checkout.domain.Region;
9	import com.loja.checkout.domain.ShippingOption;
10	import com.loja.checkout.domain.coupon.Coupon;
11	import com.loja.checkout.domain.coupon.CouponRegistry;
12	import org.springframework.stereotype.Service;
13	
14	import java.math.BigDecimal;
15	import java.math.RoundingMode;
16	import java.util.List;
17	
18	@Service
19	public class CheckoutService {
20	
21	    public CheckoutResponse calculate(CheckoutRequest req) {
22	        // 1. Validate items
23	        validateItems(req.itens());
24	        BigDecimal subtotal = computeSubtotal(req.itens());
25	        BigDecimal totalWeight = computeTotalWeight(req.itens());
26	
27	        // 2. Validate club level
28	        ClubLevel club = parseEnum(ClubLevel.class, req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
29	
30	        // 3. Validate region
31	        Region region = parseEnum(Region.class, req.regiao(), "REGIAO_INVALIDA");
32	
33	        // 4. Validate shipping option
34	        ShippingOption shipping = parseEnum(ShippingOption.class, req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
35	
36	        // 5. Check shipping availability
37	        if (!shipping.isAvailable(totalWeight)) throw new CheckoutError("MODALIDADE_INDISPONIVEL");
38	
39	        BigDecimal frete = club.freeShipping()
40	                ? BigDecimal.ZERO.setScale(2)
41	                : shipping.cost(totalWeight);
42	
43	        // 6. Validate coupon (if provided)
44	        Coupon coupon = null;
45	        if (req.cupom() != null && !req.cupom().isBlank()) {
46	            coupon = CouponRegistry.find(req.cupom())
47	                    .orElseThrow(() -> new CheckoutError("CUPOM_INVALIDO"));
48	            // 7. Check coupon applicability
49	            if (!coupon.isApplicable(subtotal, req.itens())) throw new CheckoutError("CUPOM_NAO_APLICAVEL");
50	        }
51	
52	        BigDecimal descontoCupom = coupon != null
53	                ? coupon.discount(subtotal, req.itens(), frete)
54	                : BigDecimal.ZERO.setScale(2);
55	
56	        BigDecimal seguro = region.insuranceOn(subtotal);
57	        BigDecimal orderTotal = subtotal.subtract(descontoCupom).add(frete).add(seguro);
58	
59	        // 8. Validate payment method
60	        PaymentMethod payment = parseEnum(PaymentMethod.class, req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
61	
62	        int parcelas = req.parcelas() != null ? req.parcelas() : 1;
63	
64	        // 9. Validate parcelas
65	        if (!payment.validParcelas(parcelas)) throw new CheckoutError("PARCELAMENTO_INVALIDO");
66	
67	        // 10. Check payment availability
68	        if (!payment.isAvailable(orderTotal)) throw new CheckoutError("FORMA_PAGAMENTO_INDISPONIVEL");
69	
70	        BigDecimal totalFinal = payment.finalTotal(orderTotal, parcelas);
71	        BigDecimal valorParcela = payment.installmentValue(orderTotal, parcelas);
72	        BigDecimal ajuste = totalFinal.subtract(orderTotal);
73	
74	        BigDecimal credito = club.cashbackOn(subtotal);
75	        boolean brinde = club.hasGiftAbove(subtotal);
76	
77	        return new CheckoutResponse(
78	                subtotal, descontoCupom, frete, shipping.deliveryDays(),
79	                seguro, ajuste, totalFinal, parcelas, valorParcela, credito, brinde
80	        );
81	    }
82	
83	    private void validateItems(List<CartItem> items) {
84	        if (items == null || items.isEmpty()) throw new CheckoutError("PEDIDO_INVALIDO");
85	        for (CartItem item : items) {
86	            if (item.precoUnitario() == null || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
87	                    || item.quantidade() == null || item.quantidade() <= 0
88	                    || item.pesoKg() == null || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
89	                throw new CheckoutError("PEDIDO_INVALIDO");
90	            }
91	        }
92	    }
93	
94	    private BigDecimal computeSubtotal(List<CartItem> items) {
95	        BigDecimal sum = BigDecimal.ZERO;
96	        for (CartItem item : items) {
97	            sum = sum.add(item.precoUnitario().multiply(BigDecimal.valueOf(item.quantidade())));
98	        }
99	        return sum.setScale(2, RoundingMode.HALF_EVEN);
100	    }
101	
102	    private BigDecimal computeTotalWeight(List<CartItem> items) {
103	        BigDecimal sum = BigDecimal.ZERO;
104	        for (CartItem item : items) {
105	            sum = sum.add(item.pesoKg().multiply(BigDecimal.valueOf(item.quantidade())));
106	        }
107	        return sum;
108	    }
109	
110	    private <T extends Enum<T>> T parseEnum(Class<T> cls, String value, String errorCode) {
111	        if (value == null || value.isBlank()) throw new CheckoutError(errorCode);
112	        try {
113	            return Enum.valueOf(cls, value);
114	        } catch (IllegalArgumentException e) {
115	            throw new CheckoutError(errorCode);
116	        }
117	    }
