1	package com.loja.checkout.domain;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	
6	public enum PaymentMethod {
7	    PIX {
8	        @Override public boolean validParcelas(int p) { return p == 1; }
9	        @Override public boolean isAvailable(BigDecimal total) { return true; }
10	        @Override
11	        public BigDecimal finalTotal(BigDecimal total, int p) {
12	            BigDecimal discount = total.multiply(PIX_RATE).setScale(2, RoundingMode.HALF_EVEN);
13	            return total.subtract(discount);
14	        }
15	        @Override public BigDecimal installmentValue(BigDecimal total, int p) { return finalTotal(total, p); }
16	    },
17	    BOLETO {
18	        @Override public boolean validParcelas(int p) { return p == 1; }
19	        @Override
20	        public boolean isAvailable(BigDecimal total) {
21	            return total.compareTo(BOLETO_MAX) <= 0;
22	        }
23	        @Override public BigDecimal finalTotal(BigDecimal total, int p) { return total.add(BOLETO_FEE); }
24	        @Override public BigDecimal installmentValue(BigDecimal total, int p) { return finalTotal(total, p); }
25	    },
26	    CARTAO {
27	        @Override public boolean validParcelas(int p) { return p >= 1 && p <= 12; }
28	        @Override public boolean isAvailable(BigDecimal total) { return true; }
29	        @Override
30	        public BigDecimal finalTotal(BigDecimal total, int p) {
31	            if (p <= 3) return total;
32	            return installmentValue(total, p).multiply(BigDecimal.valueOf(p));
33	        }
34	        @Override
35	        public BigDecimal installmentValue(BigDecimal total, int p) {
36	            if (p <= 3) {
37	                return total.divide(BigDecimal.valueOf(p), 2, RoundingMode.HALF_EVEN);
38	            }
39	            BigDecimal onePlusRateN = BigDecimal.ONE.add(CARD_RATE).pow(p);
40	            BigDecimal factor = BigDecimal.ONE.subtract(
41	                    BigDecimal.ONE.divide(onePlusRateN, 15, RoundingMode.HALF_EVEN));
42	            return total.multiply(CARD_RATE)
43	                    .divide(factor, 15, RoundingMode.HALF_EVEN)
44	                    .setScale(2, RoundingMode.HALF_EVEN);
45	        }
46	    };
47	
48	    private static final BigDecimal PIX_RATE = new BigDecimal("0.05");
49	    private static final BigDecimal BOLETO_FEE = new BigDecimal("3.49");
50	    private static final BigDecimal BOLETO_MAX = new BigDecimal("1000.00");
51	    private static final BigDecimal CARD_RATE = new BigDecimal("0.0199");
52	
53	    public abstract boolean validParcelas(int parcelas);
54	    public abstract boolean isAvailable(BigDecimal orderTotal);
55	    public abstract BigDecimal finalTotal(BigDecimal orderTotal, int parcelas);
56	    public abstract BigDecimal installmentValue(BigDecimal orderTotal, int parcelas);
57	}
